<?php

use Illuminate\Support\Facades\Route; use App\Http\Controllers\{AdminController,AdminServiceController,CustomerLocationController,PublicController,QuoteController,TelegramController};

Route::post('/telegram/webhook', [TelegramController::class, 'webhook'])->middleware('throttle:telegram-webhook')->name('telegram.webhook');

Route::get('/',[PublicController::class,'home'])->name('home'); Route::get('/pedido',[PublicController::class,'create'])->name('orders.create'); Route::post('/pedido/calcular',[PublicController::class,'calculate'])->middleware('throttle:order-preview')->name('orders.calculate'); Route::post('/pedido',[PublicController::class,'store'])->middleware('throttle:order-submit')->name('orders.store'); Route::get('/pedido/{code}/{token}',[PublicController::class,'show'])->name('orders.show'); Route::match(['get','post'],'/consultar',[PublicController::class,'lookup'])->name('orders.lookup');
Route::get('/cotizacion/{token}',[QuoteController::class,'show'])->name('quotes.show'); Route::post('/cotizacion/{token}',[QuoteController::class,'respond'])->middleware('throttle:10,1')->name('quotes.respond');
Route::get('/pedido/{code}/{token}/ubicacion',[CustomerLocationController::class,'edit'])->name('orders.location.edit');
Route::post('/pedido/{code}/{token}/ubicacion/calcular',[CustomerLocationController::class,'preview'])->middleware('throttle:30,1')->name('orders.location.preview');
Route::post('/pedido/{code}/{token}/ubicacion',[CustomerLocationController::class,'update'])->middleware('throttle:10,1')->name('orders.location.update');
Route::get('/admin/login',[AdminController::class,'login'])->name('login'); Route::post('/admin/login',[AdminController::class,'authenticate'])->middleware('throttle:5,1');
Route::middleware('auth')->prefix('admin')->name('admin.')->group(function(){Route::post('/logout',[AdminController::class,'logout'])->name('logout');Route::get('/',[AdminController::class,'dashboard'])->name('dashboard');Route::get('/pedidos',[AdminController::class,'orders'])->name('orders.index');Route::get('/pedidos/{order}',[AdminController::class,'order'])->name('orders.show');Route::post('/pedidos/{order}/estado',[AdminController::class,'status'])->name('orders.status');Route::post('/pedidos/{order}/ubicacion',[AdminController::class,'location'])->name('orders.location');Route::post('/pedidos/{order}/cotizacion',[AdminController::class,'quote'])->name('orders.quote');Route::post('/pedidos/{order}/pago',[AdminController::class,'payment'])->name('orders.payment');Route::get('/pedidos/{order}/archivo/{file}',[AdminController::class,'download'])->name('files.download');Route::get('/configuracion',[AdminController::class,'settings'])->name('settings.edit');Route::post('/configuracion',[AdminController::class,'settings'])->name('settings.update');});
Route::middleware('auth')->prefix('admin')->name('admin.')->group(function(){Route::post('/telegram/conectar',[TelegramController::class,'connect'])->name('telegram.connect');Route::post('/telegram/prueba',[TelegramController::class,'test'])->middleware('throttle:telegram-test')->name('telegram.test');Route::delete('/telegram/desconectar',[TelegramController::class,'disconnect'])->name('telegram.disconnect');Route::post('/pedidos/{order}/revisado',[TelegramController::class,'review'])->name('orders.review');Route::get('/notificaciones/poll',[TelegramController::class,'poll'])->middleware('throttle:30,1')->name('notifications.poll');});
Route::middleware('auth')->prefix('admin/servicios')->name('admin.services.')->group(function(){Route::get('/',[AdminServiceController::class,'index'])->name('index');Route::get('/crear',[AdminServiceController::class,'create'])->name('create');Route::post('/',[AdminServiceController::class,'store'])->name('store');Route::post('/orden',[AdminServiceController::class,'reorder'])->name('reorder');Route::get('/{service}/editar',[AdminServiceController::class,'edit'])->name('edit');Route::put('/{service}',[AdminServiceController::class,'update'])->name('update');Route::post('/{service}/duplicar',[AdminServiceController::class,'duplicate'])->name('duplicate');Route::patch('/{service}/estado',[AdminServiceController::class,'toggle'])->name('toggle');Route::delete('/{service}',[AdminServiceController::class,'destroy'])->name('destroy');});
Route::middleware('auth')->prefix('admin')->name('admin.')->group(function(){Route::post('/pedidos/{order}/cotizaciones/{quote}/enviado',[AdminController::class,'markQuoteSent'])->name('quotes.sent');Route::post('/pedidos/{order}/cotizaciones/{quote}/respuesta',[AdminController::class,'quoteResponse'])->name('quotes.response');Route::post('/pedidos/{order}/domicilio',[AdminController::class,'deliveryReview'])->name('orders.delivery-review');Route::post('/pedidos/{order}/ubicacion-cambios/{change}/revisado',[AdminController::class,'locationChangeReviewed'])->name('location-changes.reviewed');Route::post('/pedidos/{order}/ubicacion-cambios/{change}/aprobar',[AdminController::class,'locationChangeApprove'])->name('location-changes.approve');Route::post('/pedidos/{order}/ubicacion-cambios/{change}/rechazar',[AdminController::class,'locationChangeReject'])->name('location-changes.reject');});
